        );
    }

    @Test
    void whenCreateBook_thenBookIsSavedAndReturned() {
        // given
        when(bookRepository.save(any(Book.class))).thenAnswer(invocation -> {
            Book b = invocation.getArgument(0);
            b.setId(1L);
            return b;
        });

        // when
        Book created = bookService.create(bookDto);

        // then
        assertNotNull(created.getId());
        assertEquals(bookDto.getTitle(), created.getTitle());
        verify(bookRepository, times(1)).save(any(Book.class));
    }

    @Test
    void whenGetExistingBookById_thenReturnBook() {
        // given
        given(bookRepository.findById(1L)).willReturn(Optional.of(book));

        // when
        Book found = bookService.getById(1L);

        // then
        assertNotNull(found);
        assertEquals(book.getId(), found.getId());
        verify(bookRepository, times(1)).findById(1L);
    }

    @Test
    void whenGetNonExistingBookById_thenThrowException() {
        // given
        given(bookRepository.findById(99L)).willReturn(Optional.empty());

        // when / then
        assertThrows(RuntimeException.class, () -> bookService.getById(99L));
        verify(bookRepository, times(1)).findById(99L);
    }

    @Test
    void whenGetAllBooks_thenReturnList() {
        // given
        List<Book> books = new ArrayList<>();
        books.add(book);
        given(bookRepository.findAll()).willReturn(books);

        // when
        List<Book> result = bookService.getAll();

        // then
        assertEquals(1, result.size());
