        Book result = bookService.update(1L, updateDto);

        // then
        assertEquals(updateDto.getTitle(), result.getTitle());
        verify(bookRepository, times(1)).findById(1L);
        verify(bookRepository, times(1)).save(any(Book.class));
    }

